---@class CompeteDojo
local CompeteDojo = Class("CompeteDojo")
function CompeteDojo:__init()
    self.endTime = 0
    self.closeTime = 0
    self.startTime = 0
    self.pointRewardsConf = {}  -- 积分奖励
    self.playerPeopleId = 0
    self.playerRank = {}
    self.activityConf = {}
    self.taskInfo = {}
    self.giftTestConf = {}
    self.userPkPointInfo = {}
    self.activityUuid = 0
    self.activityGoodsNum = 0
end

function CompeteDojo:GetPointRewards()
    return self.pointRewardsConf
end

function CompeteDojo:GetCurrentPoint()
    local playerRank = self.playerRank or {}
    local point = checkInt(playerRank.point)
    return point
end
---获取到当前playerRank
function CompeteDojo:GetPlayerRank()
    return self.playerRank
end
--- 设置当前点数
function CompeteDojo:SetPlayerRank(playerRank)
    self.playerRank = playerRank
end

---FillVo
---@param row TableML.TableFileRow
function CompeteDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    local haskey = table.haskey
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and haskey(self, key)  then
            self[key] = value
        end
    end
    self.endTime = self:GetAtLastTime(self.endTime)
    self.closeTime = self:GetAtLastTime(self.closeTime)
    self.startTime = self:GetAtLastTime(self.startTime)
    if self.activityConf.endStoryId then
        self.activityConf.endStoryId = string.split(self.activityConf.endStoryId , ";")
    end
    if isSet(jsonData, "activityGoodsNum") then
        ---@type BackpackComponent
        local backpackComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
        if backpackComponent then
            local goodsId = checkNumber(jsonData.activityConf.prop)
            if goodsId > 0 then
                backpackComponent.backpack[tostring(goodsId)] = checkNumber(jsonData.activityGoodsNum)
            end
        end
    end
end
function CompeteDojo:GetTaskInfo()
    return self.taskInfo
end
--- 计算出最总时间
function CompeteDojo:GetAtLastTime(leftSecond)
    local lastTime = leftSecond + os.time()
    return lastTime
end
--- 获取开始时间
function CompeteDojo:GetStartTime()
    return self.startTime
end
--- 获取关闭时间
function CompeteDojo:GetEndTime()
    return self.endTime
end
--- 获取时间
function CompeteDojo:GetCloseTime()
    return self.closeTime
end


--- 设置积分奖励的状态
---@param id integer @ 积分id
---@param status integer @ 状态
function CompeteDojo:SetGrandPointStatus(id, status)
    local id = checkInt(id)
    local pointRewardsConf = self:GetPointRewards()
    for i, v in pairs(pointRewardsConf) do
        if id == checkInt(v.id) then
            v.status = status
            break
        end
    end
end

--- 获取积分奖励
---@param id integer @ 积分id
---@param status integer @ 状态
function CompeteDojo:GetGrandPoint(id)
    local id = checkInt(id)
    local pointRewardsConf = self:GetPointRewards()
    for i, v in pairs(pointRewardsConf) do
        if id == checkInt(v.id) then
            return v
        end
    end
end

--- 设置任务的状态
function CompeteDojo:SetTaskInfoStatusById(taskId, status)
    local taskInfo = self:GetTaskInfo()
    taskId = checkInt(taskId)
    for i, v in pairs(taskInfo) do
        if taskId == checkInt(v.taskId) then
            v.status = status
            break
        end
    end
end

--- 返回任务的状态
function CompeteDojo:GetTaskInfoStatusById(taskId)
    local taskInfo = self:GetTaskInfo()
    taskId = checkInt(taskId)
    for i, v in pairs(taskInfo) do
        if taskId == checkInt(v.taskId) then
            return v.status
        end
    end
end
--- 获取当前排期
function CompeteDojo:GetScheduleId()
    return self.activityConf.id
end

--- 获取应用积分
function CompeteDojo:GetPropId()
    return self.activityConf.prop
end

--- 获取活动配置
function CompeteDojo:GetActivityConf()
    return self.activityConf
end

function CompeteDojo:GetPeople()
    return self.activityConf.people
end
function CompeteDojo:GetPrefabId()
    return self.activityConf.prefab
end
function CompeteDojo:GetPlayerPeopleId()
    return checkInt(self.playerPeopleId)
end

function CompeteDojo:GetActivityUuid()
    return self.activityUuid
end

function CompeteDojo:GetUserPkPointInfo()
    return self.userPkPointInfo
end
function CompeteDojo:SetUserPkPointInfo(totalPoint)
    self.userPkPointInfo[tostring(self.playerPeopleId)] = totalPoint
end

function CompeteDojo:GetPeopleGiftConf()
    local peopleId = checkInt(self.playerPeopleId)
    local array = {}
    for i, v in pairs(self.giftTestConf) do
        if checkInt(v.people) == peopleId then
            array[#array+1] = v
        end
    end
    return array
end

function CompeteDojo:__delete()
    self.endTime = nil
    self.closeTime = nil
    self.pointRewardsConf = nil  -- 积分奖励
    self.playerPeopleId = nil
    self.playerRank = nil
    self.activityConf = nil
    self.taskInfo = nil
    self.giftTestConf = nil
    self.userPkPointInfo = nil
    self.activityUuid = nil
    self.startTime = nil
end

return CompeteDojo